insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Big Five personality traits: Extraversion', 'Extraversion is characterised by breadth of activities (as opposed to depth), surgency from external activities/situations, and energy creation from external means. The trait is marked by pronounced engagement with the external world. Extraverts enjoy interacting with people, and are often perceived as energetic. They tend to be enthusiastic and action-oriented. They possess high group visibility, like to talk, and assert themselves. Extraverts may appear more dominant in social settings, as opposed to introverts in that setting. Introverts have lower social engagement and energy levels than extraverts. They tend to seem quiet, low-key, deliberate, and less involved in the social world. Their lack of social involvement should not be interpreted as shyness or depression, but as greater independence of their social world than extraverts. Introverts need less stimulation and more time alone than extraverts. This does not mean that they are unfriendly or antisocial; rather, they are aloof and reserved in social situations. Generally, people are a combination of extraversion and introversion, with personality psychologist Hans Eysenck suggesting a model by which differences in their brains produce these traits.', 'Wikipedia: Big Five personality traits', 'https://en.wikipedia.org/w/index.php?title=Big_Five_personality_traits&oldid=1381323693', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Extraversion is characterised by breadth of activities (as opposed to depth), surgency from external activities/situations, and energy creation from external means. The trait is marked by pronounced engagement with the external world. Extraverts enjoy interacting with people, and are often perceived as energetic. They tend to be enthusiastic and action-oriented. They possess high group visibility, like to talk, and assert themselves. Extraverts may appear more dominant in social settings, as opposed to introverts in that setting. Introverts have lower social engagement and energy levels than extraverts. They tend to seem quiet, low-key, deliberate, and less involved in the social world. Their lack of social involvement should not be interpreted as shyness or depression, but as greater independence of their social world than extraverts. Introverts need less stimulation and more time alone than extraverts. This does not mean that they are unfriendly or antisocial; rather, they are aloof and reserved in social situations. Generally, people are a combination of extraversion and introversion, with personality psychologist Hans Eysenck suggesting a model by which differences in their brains produce these traits.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Big Five personality traits: Agreeableness', 'Agreeableness is the general concern for social harmony. Agreeable individuals value getting along with others. They are generally considerate, kind, generous, trusting and trustworthy, helpful, and willing to compromise their interests with others. Agreeable people also have an optimistic view of human nature. Agreeableness is associated with mental health. Disagreeable individuals place self-interest above getting along with others. They are generally unconcerned with others'' well-being and are less likely to extend themselves for other people. Sometimes their skepticism about others'' motives causes them to be suspicious, unfriendly, and uncooperative. Disagreeable people are often competitive or challenging, which can be seen as argumentative or untrustworthy. Because agreeableness is a social trait, research has shown that one''s agreeableness positively correlates with the quality of relationships with one''s team members. Agreeableness also positively predicts transformational leadership skills. In a study conducted among 169 participants in leadership positions in a variety of professions, individuals were asked to take a personality test and be directly evaluated by supervised subordinates. Very agreeable leaders were more likely to be considered transformational rather than transactional. Although the relationship was not strong (r=0.32, β=0.28, p<0.01), it was the strongest of the Big Five traits. However, the same study could not predict leadership effectiveness as evaluated by the leader''s direct supervisor.', 'Wikipedia: Big Five personality traits', 'https://en.wikipedia.org/w/index.php?title=Big_Five_personality_traits&oldid=1381323693', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Agreeableness is the general concern for social harmony. Agreeable individuals value getting along with others. They are generally considerate, kind, generous, trusting and trustworthy, helpful, and willing to compromise their interests with others. Agreeable people also have an optimistic view of human nature. Agreeableness is associated with mental health. Disagreeable individuals place self-interest above getting along with others. They are generally unconcerned with others'' well-being and are less likely to extend themselves for other people. Sometimes their skepticism about others'' motives causes them to be suspicious, unfriendly, and uncooperative. Disagreeable people are often competitive or challenging, which can be seen as argumentative or untrustworthy. Because agreeableness is a social trait, research has shown that one''s agreeableness positively correlates with the quality of relationships with one''s team members. Agreeableness also positively predicts transformational leadership skills. In a study conducted among 169 participants in leadership positions in a variety of professions, individuals were asked to take a personality test and be directly evaluated by supervised subordinates. Very agreeable leaders were more likely to be considered transformational rather than transactional. Although the relationship was not strong (r=0.32, β=0.28, p<0.01), it was the strongest of the Big Five traits. However, the same study could not predict leadership effectiveness as evaluated by the leader''s direct supervisor.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego', 'In psychoanalytic theory, the id, ego, and superego are three distinct, interacting agents in the psychic apparatus, outlined in Sigmund Freud''s structural model of the psyche. The three agents are theoretical constructs that Freud employed to describe the basic structure of mental life as it was encountered in psychoanalytic practice. Freud himself used the German terms das Es, Ich, and Über-Ich, which literally translate as "the it", "I", and "over-I". The Latin terms id, ego and superego were chosen by his original translators and have remained in use. The structural model was introduced in Freud''s essay Beyond the Pleasure Principle (1920) and further refined and formalised in later essays such as The Ego and the Id (1923). Freud developed the model in response to the perceived ambiguity of the terms "conscious" and "unconscious" in his earlier topographical model.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'In psychoanalytic theory, the id, ego, and superego are three distinct, interacting agents in the psychic apparatus, outlined in Sigmund Freud''s structural model of the psyche. The three agents are theoretical constructs that Freud employed to describe the basic structure of mental life as it was encountered in psychoanalytic practice. Freud himself used the German terms das Es, Ich, and Über-Ich, which literally translate as "the it", "I", and "over-I". The Latin terms id, ego and superego were chosen by his original translators and have remained in use. The structural model was introduced in Freud''s essay Beyond the Pleasure Principle (1920) and further refined and formalised in later essays such as The Ego and the Id (1923). Freud developed the model in response to the perceived ambiguity of the terms "conscious" and "unconscious" in his earlier topographical model.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego', 'Broadly speaking, the id is the organism''s unconscious array of uncoordinated instinctual needs, impulses and desires; the superego is the part of the psyche that has internalised social rules and norms, largely in response to parental demands and prohibitions in childhood; the ego is the integrative agent that directs activity based on mediation between the id''s energies, the demands of external reality, and the moral and critical constraints of the superego. Freud compared the ego, in its relation to the id, to a man on horseback: the rider must harness and direct the superior energy of his mount, and at times allow for a practicable satisfaction of its urges. The ego is thus "in the habit of transforming the id''s will into action, as if it were its own."', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Broadly speaking, the id is the organism''s unconscious array of uncoordinated instinctual needs, impulses and desires; the superego is the part of the psyche that has internalised social rules and norms, largely in response to parental demands and prohibitions in childhood; the ego is the integrative agent that directs activity based on mediation between the id''s energies, the demands of external reality, and the moral and critical constraints of the superego. Freud compared the ego, in its relation to the id, to a man on horseback: the rider must harness and direct the superior energy of his mount, and at times allow for a practicable satisfaction of its urges. The ego is thus "in the habit of transforming the id''s will into action, as if it were its own."');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: History and translation of the terms', 'The terms "id", "ego", and "superego" are not Freud''s own; they are Latinisations by his translator James Strachey. Freud himself wrote of "das Es", "das Ich", and "das Über-Ich"—respectively, "the It", "the I", and "the Over-I". Thus, to the German reader, Freud''s original terms are to some degree self-explanatory. The term "das Es" was originally used by Georg Groddeck, a physician whose unconventional ideas were of interest to Freud (Groddeck''s translators render the term in English as "the It"). The word ego is taken directly from Latin, where it is the nominative of the first person singular personal pronoun and is translated as "I myself" to express emphasis. Figures like Bruno Bettelheim have criticised the way "the English translations impeded students'' efforts to gain a true understanding of Freud" by substituting the formalised language of the elaborated code for the quotidian immediacy of Freud''s own language.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'The terms "id", "ego", and "superego" are not Freud''s own; they are Latinisations by his translator James Strachey. Freud himself wrote of "das Es", "das Ich", and "das Über-Ich"—respectively, "the It", "the I", and "the Over-I". Thus, to the German reader, Freud''s original terms are to some degree self-explanatory. The term "das Es" was originally used by Georg Groddeck, a physician whose unconventional ideas were of interest to Freud (Groddeck''s translators render the term in English as "the It"). The word ego is taken directly from Latin, where it is the nominative of the first person singular personal pronoun and is translated as "I myself" to express emphasis. Figures like Bruno Bettelheim have criticised the way "the English translations impeded students'' efforts to gain a true understanding of Freud" by substituting the formalised language of the elaborated code for the quotidian immediacy of Freud''s own language.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: Id', 'Freud conceived of the id as the unconscious source of bodily needs, impulses and desires, especially those related to aggression and the sexual drive. The id acts according to the pleasure principle—the psychic force oriented to the immediate gratification of impulse and desire. Freud described the id as "the dark, inaccessible part of our personality". Understanding of it is limited to analysis of dreams and neurotic symptoms, and it can only be described in terms of its contrast with the ego. It has no organisation and no collective will: it is concerned only with the satisfaction of drives in accordance with the pleasure principle. It is oblivious to reason and the presumptions of ordinary conscious life: "contrary impulses exist side by side, without cancelling each other... There is nothing in the id that could be compared with negation... nothing in the id which corresponds to the idea of time." The id "knows no judgements of value: no good and evil, no morality....Instinctual cathexes seeking discharge—that, in our view, is all there is in the id."', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Freud conceived of the id as the unconscious source of bodily needs, impulses and desires, especially those related to aggression and the sexual drive. The id acts according to the pleasure principle—the psychic force oriented to the immediate gratification of impulse and desire. Freud described the id as "the dark, inaccessible part of our personality". Understanding of it is limited to analysis of dreams and neurotic symptoms, and it can only be described in terms of its contrast with the ego. It has no organisation and no collective will: it is concerned only with the satisfaction of drives in accordance with the pleasure principle. It is oblivious to reason and the presumptions of ordinary conscious life: "contrary impulses exist side by side, without cancelling each other... There is nothing in the id that could be compared with negation... nothing in the id which corresponds to the idea of time." The id "knows no judgements of value: no good and evil, no morality....Instinctual cathexes seeking discharge—that, in our view, is all there is in the id."');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: Id', 'Developmentally, the id precedes the ego. The id consists of the basic instinctual drives that are present at birth, inherent in the somatic organisation, and governed only by the pleasure principle. The psychic apparatus begins as an undifferentiated id, part of which then develops into a structured "ego", a concept of self as an integrated unity that takes the principle of reality into account. Freud describes the id as "the great reservoir of libido", the energy of desire, usually conceived as sexual in nature, the life instincts that are constantly seeking a renewal of life. He later also postulated a death drive, which seeks "to lead organic life back into the inanimate state." For Freud, "the death instinct would thus seem to express itself—though probably only in part—as an instinct of destruction directed against the external world and other organisms" through aggression. Since the id includes all instinctual impulses, the destructive instinct, as well as eros or the life instincts, is considered to be part of the id.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Developmentally, the id precedes the ego. The id consists of the basic instinctual drives that are present at birth, inherent in the somatic organisation, and governed only by the pleasure principle. The psychic apparatus begins as an undifferentiated id, part of which then develops into a structured "ego", a concept of self as an integrated unity that takes the principle of reality into account. Freud describes the id as "the great reservoir of libido", the energy of desire, usually conceived as sexual in nature, the life instincts that are constantly seeking a renewal of life. He later also postulated a death drive, which seeks "to lead organic life back into the inanimate state." For Freud, "the death instinct would thus seem to express itself—though probably only in part—as an instinct of destruction directed against the external world and other organisms" through aggression. Since the id includes all instinctual impulses, the destructive instinct, as well as eros or the life instincts, is considered to be part of the id.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: Ego', 'The ego acts according to the reality principle. It analyses complex perceptions (things, ideas, dreams), synthesises the appropriate parts into logically coherent interpretations (also models) and rules the muscular apparatus. Since the id''s drives are frequently incompatible with the moral prescriptions and religious illusions of contemporary cultures, the ego attempts to direct the libidinal energy and satisfy its demands in accordance with the imperatives of that reality. According to Freud, the ego, in its role as mediator between the id and reality, is often "obliged to cloak the (unconscious) commands of the id with its own preconscious rationalisations, to conceal the id''s conflicts with reality, to profess...to be taking notice of reality even when the id has remained rigid and unyielding." Originally, Freud used the word ego to mean the sense of self, but later expanded it to include psychic functions such as judgment, tolerance, reality testing, control, planning, defense, synthesis of information, intellectual functioning, and memory. The ego is the organizing principle upon which thoughts and interpretations of the world are based.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'The ego acts according to the reality principle. It analyses complex perceptions (things, ideas, dreams), synthesises the appropriate parts into logically coherent interpretations (also models) and rules the muscular apparatus. Since the id''s drives are frequently incompatible with the moral prescriptions and religious illusions of contemporary cultures, the ego attempts to direct the libidinal energy and satisfy its demands in accordance with the imperatives of that reality. According to Freud, the ego, in its role as mediator between the id and reality, is often "obliged to cloak the (unconscious) commands of the id with its own preconscious rationalisations, to conceal the id''s conflicts with reality, to profess...to be taking notice of reality even when the id has remained rigid and unyielding." Originally, Freud used the word ego to mean the sense of self, but later expanded it to include psychic functions such as judgment, tolerance, reality testing, control, planning, defense, synthesis of information, intellectual functioning, and memory. The ego is the organizing principle upon which thoughts and interpretations of the world are based.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: Ego', 'According to Freud, "the ego is that part of the id which has been modified by the direct influence of the external world... The ego represents what may be called reason and common sense, in contrast to the id, which contains the passions.... it is like a man on horseback, who has to hold in check the superior strength of the horse; with this difference, that the rider tries to do so with his own strength while the ego uses borrowed forces." In fact, the ego is required to serve "three severe masters...the external world, the superego and the id." It seeks to find a balance between the natural drives of the id, the limitations imposed by reality, and the strictures of the superego. It is concerned with self-preservation: it strives to keep the id''s instinctive needs within limits, adapted to reality and submissive to the superego.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'According to Freud, "the ego is that part of the id which has been modified by the direct influence of the external world... The ego represents what may be called reason and common sense, in contrast to the id, which contains the passions.... it is like a man on horseback, who has to hold in check the superior strength of the horse; with this difference, that the rider tries to do so with his own strength while the ego uses borrowed forces." In fact, the ego is required to serve "three severe masters...the external world, the superego and the id." It seeks to find a balance between the natural drives of the id, the limitations imposed by reality, and the strictures of the superego. It is concerned with self-preservation: it strives to keep the id''s instinctive needs within limits, adapted to reality and submissive to the superego.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Id, ego and superego: Ego', 'Thus, "driven by the id, confined by the superego, repulsed by reality" the ego struggles to bring about harmony among the competing forces. Consequently, it can easily be subject to "realistic anxiety regarding the external world, moral anxiety regarding the superego, and neurotic anxiety regarding the strength of the passions in the id." The ego may wish to serve the id, trying to gloss over the finer details of reality to minimise conflicts, while pretending to have a regard for reality. But the superego is constantly watching every one of the ego''s moves and punishes it with feelings of guilt, anxiety, and inferiority. To overcome this, the ego employs defense mechanisms. Defense mechanisms reduce the tension and anxiety by disguising or transforming the impulses that are perceived as threatening. Denial, displacement, intellectualisation, fantasy, compensation, projection, rationalisation, reaction formation, regression, repression, and sublimation were the defense mechanisms Freud identified. His daughter Anna Freud identified the concepts of undoing, suppression, dissociation, idealisation, identification, introjection, inversion, somatisation, splitting, and substitution. In a diagram of the Structural and Topographical Models of Mind, the ego is depicted as being half in the conscious, a quarter in the preconscious, and the other quarter in the unconscious.', 'Wikipedia: Id, ego and superego', 'https://en.wikipedia.org/w/index.php?title=Id%2C_ego_and_superego&oldid=1373472804', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Thus, "driven by the id, confined by the superego, repulsed by reality" the ego struggles to bring about harmony among the competing forces. Consequently, it can easily be subject to "realistic anxiety regarding the external world, moral anxiety regarding the superego, and neurotic anxiety regarding the strength of the passions in the id." The ego may wish to serve the id, trying to gloss over the finer details of reality to minimise conflicts, while pretending to have a regard for reality. But the superego is constantly watching every one of the ego''s moves and punishes it with feelings of guilt, anxiety, and inferiority. To overcome this, the ego employs defense mechanisms. Defense mechanisms reduce the tension and anxiety by disguising or transforming the impulses that are perceived as threatening. Denial, displacement, intellectualisation, fantasy, compensation, projection, rationalisation, reaction formation, regression, repression, and sublimation were the defense mechanisms Freud identified. His daughter Anna Freud identified the concepts of undoing, suppression, dissociation, idealisation, identification, introjection, inversion, somatisation, splitting, and substitution. In a diagram of the Structural and Topographical Models of Mind, the ego is depicted as being half in the conscious, a quarter in the preconscious, and the other quarter in the unconscious.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder', 'A mental disorder, also referred to as a mental illness, a mental health condition, or a psychiatric disability, is a behavioral or mental pattern that causes significant distress or impairment of personal functioning. A mental disorder is also characterized by a clinically significant disturbance in an individual''s cognition, emotional regulation, or behavior, often in a social context. Such disturbances may occur as single episodes, may be persistent, or may be relapsing–remitting. There are many different types of mental disorders, with signs and symptoms that vary widely between specific disorders. A mental disorder is one aspect of mental health. The causes of mental disorders are often unclear. Theories incorporate findings from a range of fields. Disorders may be associated with particular regions or functions of the brain. Disorders are usually diagnosed or assessed by a mental health professional, such as a clinical psychologist, psychiatrist, psychiatric nurse, or clinical social worker, using various methods such as psychometric tests, but often relying on observation and questioning. Cultural and religious beliefs, as well as social norms, should be taken into account when making a diagnosis.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'A mental disorder, also referred to as a mental illness, a mental health condition, or a psychiatric disability, is a behavioral or mental pattern that causes significant distress or impairment of personal functioning. A mental disorder is also characterized by a clinically significant disturbance in an individual''s cognition, emotional regulation, or behavior, often in a social context. Such disturbances may occur as single episodes, may be persistent, or may be relapsing–remitting. There are many different types of mental disorders, with signs and symptoms that vary widely between specific disorders. A mental disorder is one aspect of mental health. The causes of mental disorders are often unclear. Theories incorporate findings from a range of fields. Disorders may be associated with particular regions or functions of the brain. Disorders are usually diagnosed or assessed by a mental health professional, such as a clinical psychologist, psychiatrist, psychiatric nurse, or clinical social worker, using various methods such as psychometric tests, but often relying on observation and questioning. Cultural and religious beliefs, as well as social norms, should be taken into account when making a diagnosis.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder', 'Services for mental disorders are usually based in psychiatric hospitals, outpatient clinics, or in the community. Treatments are provided by mental health professionals. Common treatment options are psychotherapy or psychiatric medication, while lifestyle changes, social interventions, peer support, and self-help are also options. In a minority of cases, there may be involuntary detention or treatment. Prevention programs have been shown to reduce depression. In 2019, common mental disorders around the globe include: major depression, which affects about 264 million people; dementia, which affects about 50 million; bipolar disorder, which affects about 45 million; and schizophrenia and other psychoses, which affect about 20 million people. Neurodevelopmental disorders include attention deficit hyperactivity disorder (ADHD), autism spectrum disorder (autism), and intellectual disability, of which onset occurs early in the developmental period. Stigma and discrimination can add to the suffering and disability associated with mental disorders, leading to various social movements attempting to increase understanding and challenge social exclusion.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Services for mental disorders are usually based in psychiatric hospitals, outpatient clinics, or in the community. Treatments are provided by mental health professionals. Common treatment options are psychotherapy or psychiatric medication, while lifestyle changes, social interventions, peer support, and self-help are also options. In a minority of cases, there may be involuntary detention or treatment. Prevention programs have been shown to reduce depression. In 2019, common mental disorders around the globe include: major depression, which affects about 264 million people; dementia, which affects about 50 million; bipolar disorder, which affects about 45 million; and schizophrenia and other psychoses, which affect about 20 million people. Neurodevelopmental disorders include attention deficit hyperactivity disorder (ADHD), autism spectrum disorder (autism), and intellectual disability, of which onset occurs early in the developmental period. Stigma and discrimination can add to the suffering and disability associated with mental disorders, leading to various social movements attempting to increase understanding and challenge social exclusion.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Definition', 'The definition and classification of mental disorders are key issues for researchers as well as service providers and those who may be diagnosed. For a mental state to be classified as a disorder, it generally needs to cause dysfunction. Most international clinical documents use the term mental "disorder", while "illness" is also common. It has been noted that using the term "mental" (i.e., of the mind) is not necessarily meant to imply separateness from the brain or body, although the distinction between mind and brain, as well as the question of their fundamental nature, is often insufficiently examined in psychiatry. According to the fourth edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-IV), published in 1994, a mental disorder is a psychological syndrome or pattern that is associated with distress (e.g., via a painful symptom), disability (impairment in one or more important areas of functioning), increased risk of death, or causes a significant loss of autonomy; however, it excludes normal responses such as the grief from loss of a loved one and also excludes deviant behavior for political, religious, or societal reasons not arising from a dysfunction in the individual.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'The definition and classification of mental disorders are key issues for researchers as well as service providers and those who may be diagnosed. For a mental state to be classified as a disorder, it generally needs to cause dysfunction. Most international clinical documents use the term mental "disorder", while "illness" is also common. It has been noted that using the term "mental" (i.e., of the mind) is not necessarily meant to imply separateness from the brain or body, although the distinction between mind and brain, as well as the question of their fundamental nature, is often insufficiently examined in psychiatry. According to the fourth edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM-IV), published in 1994, a mental disorder is a psychological syndrome or pattern that is associated with distress (e.g., via a painful symptom), disability (impairment in one or more important areas of functioning), increased risk of death, or causes a significant loss of autonomy; however, it excludes normal responses such as the grief from loss of a loved one and also excludes deviant behavior for political, religious, or societal reasons not arising from a dysfunction in the individual.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Definition', 'The DSM-IV definition states that, like many medical terms, mental disorder "lacks a consistent operational definition that covers all situations". It notes that different levels of abstraction can be used for medical definitions, including pathology, symptomology, deviance from a normal range, or etiology, and that the same is true for mental disorders, so that sometimes one type of definition is appropriate and sometimes another, depending on the situation. In 2013, the American Psychiatric Association (APA) redefined mental disorders in the DSM-5 as "a syndrome characterized by clinically significant disturbance in an individual''s cognition, emotion regulation, or behavior that reflects a dysfunction in the psychological, biological, or developmental processes underlying mental functioning." The final draft of ICD-11 contains a very similar definition.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'The DSM-IV definition states that, like many medical terms, mental disorder "lacks a consistent operational definition that covers all situations". It notes that different levels of abstraction can be used for medical definitions, including pathology, symptomology, deviance from a normal range, or etiology, and that the same is true for mental disorders, so that sometimes one type of definition is appropriate and sometimes another, depending on the situation. In 2013, the American Psychiatric Association (APA) redefined mental disorders in the DSM-5 as "a syndrome characterized by clinically significant disturbance in an individual''s cognition, emotion regulation, or behavior that reflects a dysfunction in the psychological, biological, or developmental processes underlying mental functioning." The final draft of ICD-11 contains a very similar definition.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Nervous illness', 'A mental breakdown, nervous breakdown or mental health crisis is an acute, time-limited, mental disorder that manifests primarily as severe, stress-induced depression, anxiety, paranoia, or dissociation in a previously functional individual, to the extent that they are no longer able to function on a day-to-day basis until the disorder is resolved. A nervous breakdown is often closely tied to psychological burnout, severe overwork, sleep deprivation, and similar stressors, which may combine to temporarily overwhelm an individual with otherwise sound mental functions. A mental breakdown can last for hours at a time, to months at a time. While these time periods can vary between different people, their reactions to the mental breakdown may also vary. These terms have not been formally defined through a medical diagnostic system such as the DSM-5 or ICD-10 and are nearly absent from scientific literature regarding mental illness. In addition to the concept of mental disorder, some people have argued for a return to the old-fashioned concept of nervous illness. In How Everyone Became Depressed: The Rise and Fall of the Nervous Breakdown (2013), Edward Shorter, a professor of psychiatry and the history of medicine, says:', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'A mental breakdown, nervous breakdown or mental health crisis is an acute, time-limited, mental disorder that manifests primarily as severe, stress-induced depression, anxiety, paranoia, or dissociation in a previously functional individual, to the extent that they are no longer able to function on a day-to-day basis until the disorder is resolved. A nervous breakdown is often closely tied to psychological burnout, severe overwork, sleep deprivation, and similar stressors, which may combine to temporarily overwhelm an individual with otherwise sound mental functions. A mental breakdown can last for hours at a time, to months at a time. While these time periods can vary between different people, their reactions to the mental breakdown may also vary. These terms have not been formally defined through a medical diagnostic system such as the DSM-5 or ICD-10 and are nearly absent from scientific literature regarding mental illness. In addition to the concept of mental disorder, some people have argued for a return to the old-fashioned concept of nervous illness. In How Everyone Became Depressed: The Rise and Fall of the Nervous Breakdown (2013), Edward Shorter, a professor of psychiatry and the history of medicine, says:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Nervous illness', 'We have had nervous illness for centuries. When you are too nervous to function... it is a nervous breakdown. But that term has vanished from medicine, although not from the way we speak.... The nervous patients of yesteryear are the depressives of today. That is the bad news.... There is a deeper illness that drives depression and the symptoms of mood. We can call this deeper illness something else, or invent a neologism, but we need to get the discussion off depression and onto this deeper disorder in the brain and body. That is the point. In eliminating the nervous breakdown, psychiatry has come close to having its own nervous breakdown.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'We have had nervous illness for centuries. When you are too nervous to function... it is a nervous breakdown. But that term has vanished from medicine, although not from the way we speak.... The nervous patients of yesteryear are the depressives of today. That is the bad news.... There is a deeper illness that drives depression and the symptoms of mood. We can call this deeper illness something else, or invent a neologism, but we need to get the discussion off depression and onto this deeper disorder in the brain and body. That is the point. In eliminating the nervous breakdown, psychiatry has come close to having its own nervous breakdown.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Classifications', 'International Classification of Diseases produced by the WHO. The latest edition is the ICD-11, which is in effect since 1 January 2022. The ICD is a broad medical classification system; mental disorders are contained in Chapter 06: Mental, behavioural or neurodevelopmental disorders (06). Diagnostic and Statistical Manual of Mental Disorders produced by the American Psychiatric Association since 1952. The latest edition is the Fifth Edition, Text Revision (DSM-5-TR), which was released in 2022. Both of these list categories of disorder and provide standardized criteria for diagnosis. They have deliberately converged their codes in recent revisions so that the manuals are often broadly comparable, although significant differences remain. Other classification schemes may be used in non-western cultures, for example, the Chinese Classification of Mental Disorders, and other manuals may be used by those of alternative theoretical persuasions, such as the Psychodynamic Diagnostic Manual. In general, mental disorders are classified separately from neurological disorders, learning disabilities or intellectual disability. Additionally, there are separate diagnostic schemes for mental illness in intellectual disability, such as the American Diagnostic Manual - Intellectual Disability and the British DC-LD.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'International Classification of Diseases produced by the WHO. The latest edition is the ICD-11, which is in effect since 1 January 2022. The ICD is a broad medical classification system; mental disorders are contained in Chapter 06: Mental, behavioural or neurodevelopmental disorders (06). Diagnostic and Statistical Manual of Mental Disorders produced by the American Psychiatric Association since 1952. The latest edition is the Fifth Edition, Text Revision (DSM-5-TR), which was released in 2022. Both of these list categories of disorder and provide standardized criteria for diagnosis. They have deliberately converged their codes in recent revisions so that the manuals are often broadly comparable, although significant differences remain. Other classification schemes may be used in non-western cultures, for example, the Chinese Classification of Mental Disorders, and other manuals may be used by those of alternative theoretical persuasions, such as the Psychodynamic Diagnostic Manual. In general, mental disorders are classified separately from neurological disorders, learning disabilities or intellectual disability. Additionally, there are separate diagnostic schemes for mental illness in intellectual disability, such as the American Diagnostic Manual - Intellectual Disability and the British DC-LD.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Mental disorder: Classifications', 'Unlike the DSM and ICD, some approaches are not based on identifying distinct categories of disorder using dichotomous symptom profiles intended to separate the abnormal from the normal. There is significant scientific debate about the relative merits of categorical versus such non-categorical (or hybrid) schemes, also known as continuum or dimensional models. A spectrum approach may incorporate elements of both. In the scientific and academic literature on the definition or classification of mental disorder, one extreme argues that it is entirely a matter of value judgements (including of what is normal) while another proposes that it is or could be entirely objective and scientific (including by reference to statistical norms). Common hybrid views argue that the concept of mental disorder is objective even if only a "fuzzy prototype" that can never be precisely defined, or conversely that the concept always involves a mixture of scientific facts and subjective value judgments. Although the diagnostic categories are referred to as ''disorders'', they are presented as medical diseases, but are not validated in the same way as most medical diagnoses. Some neurologists argue that classification will only be reliable and valid when based on neurobiological features rather than clinical interview, while others suggest that the differing ideological and practical perspectives need to be better integrated.', 'Wikipedia: Mental disorder', 'https://en.wikipedia.org/w/index.php?title=Mental_disorder&oldid=1380401399', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Unlike the DSM and ICD, some approaches are not based on identifying distinct categories of disorder using dichotomous symptom profiles intended to separate the abnormal from the normal. There is significant scientific debate about the relative merits of categorical versus such non-categorical (or hybrid) schemes, also known as continuum or dimensional models. A spectrum approach may incorporate elements of both. In the scientific and academic literature on the definition or classification of mental disorder, one extreme argues that it is entirely a matter of value judgements (including of what is normal) while another proposes that it is or could be entirely objective and scientific (including by reference to statistical norms). Common hybrid views argue that the concept of mental disorder is objective even if only a "fuzzy prototype" that can never be precisely defined, or conversely that the concept always involves a mixture of scientific facts and subjective value judgments. Although the diagnostic categories are referred to as ''disorders'', they are presented as medical diseases, but are not validated in the same way as most medical diagnoses. Some neurologists argue that classification will only be reliable and valid when based on neurobiological features rather than clinical interview, while others suggest that the differing ideological and practical perspectives need to be better integrated.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia', 'Schizophrenia is a mental disorder characterized variously by hallucinations (typically, hearing voices), delusions, disorganized thinking or behavior, and flat or inappropriate affect. Symptoms develop gradually and typically begin during young adulthood. There is no objective diagnostic test; diagnosis is based on observed behavior, a psychiatric history that includes the person''s reported experiences, and reports of others familiar with the person. For a formal diagnosis, the described symptoms need to have been present for at least six months (according to the DSM-5) or one month (according to the ICD-11). Many people with schizophrenia have other mental disorders, especially mood, anxiety, and substance use disorders, as well as obsessive–compulsive disorder (OCD). The lifetime prevalence of schizophrenia is about 0.3% to 0.7%. In 2017, there were an estimated 1.1 million new cases and in 2022 a total of 24 million cases globally. Males are more often affected and on average have an earlier onset than females. The causes of schizophrenia may include genetic and environmental factors. Genetic factors include a variety of common and rare genetic variants. Possible environmental factors include being raised in a city, childhood adversity, cannabis use during adolescence, infections, the age of a person''s mother or father, and poor nutrition during pregnancy.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Schizophrenia is a mental disorder characterized variously by hallucinations (typically, hearing voices), delusions, disorganized thinking or behavior, and flat or inappropriate affect. Symptoms develop gradually and typically begin during young adulthood. There is no objective diagnostic test; diagnosis is based on observed behavior, a psychiatric history that includes the person''s reported experiences, and reports of others familiar with the person. For a formal diagnosis, the described symptoms need to have been present for at least six months (according to the DSM-5) or one month (according to the ICD-11). Many people with schizophrenia have other mental disorders, especially mood, anxiety, and substance use disorders, as well as obsessive–compulsive disorder (OCD). The lifetime prevalence of schizophrenia is about 0.3% to 0.7%. In 2017, there were an estimated 1.1 million new cases and in 2022 a total of 24 million cases globally. Males are more often affected and on average have an earlier onset than females. The causes of schizophrenia may include genetic and environmental factors. Genetic factors include a variety of common and rare genetic variants. Possible environmental factors include being raised in a city, childhood adversity, cannabis use during adolescence, infections, the age of a person''s mother or father, and poor nutrition during pregnancy.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia', 'About half of those diagnosed with schizophrenia will experience improvement over the long term with no further relapses, and a small proportion of these will recover completely. The other half will have a lifelong impairment. In severe cases, people may be admitted to hospitals. Social problems such as long-term unemployment, poverty, homelessness, exploitation, and victimization are commonly correlated with schizophrenia. Compared to the general population, people with schizophrenia have a higher suicide rate (about 5% overall) and more physical health problems, leading to an average decrease in life expectancy by 20 to 28 years. In 2015, an estimated 17,000 deaths were linked to schizophrenia. The mainstay of treatment is antipsychotic medication, including olanzapine and risperidone, along with counseling, job training, and social rehabilitation. Up to a third of people do not respond to initial antipsychotics, in which case clozapine is offered. Most antipsychotics improve schizophrenia symptoms, with clozapine the most effective overall; side effects vary considerably and guide treatment choices. In situations where doctors judge that there is a risk of harm to self or others, they may impose short involuntary hospitalization. Long-term hospitalization is used on a small number of people with severe schizophrenia. In some countries where supportive services are limited or unavailable, long-term hospital stays are more common.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'About half of those diagnosed with schizophrenia will experience improvement over the long term with no further relapses, and a small proportion of these will recover completely. The other half will have a lifelong impairment. In severe cases, people may be admitted to hospitals. Social problems such as long-term unemployment, poverty, homelessness, exploitation, and victimization are commonly correlated with schizophrenia. Compared to the general population, people with schizophrenia have a higher suicide rate (about 5% overall) and more physical health problems, leading to an average decrease in life expectancy by 20 to 28 years. In 2015, an estimated 17,000 deaths were linked to schizophrenia. The mainstay of treatment is antipsychotic medication, including olanzapine and risperidone, along with counseling, job training, and social rehabilitation. Up to a third of people do not respond to initial antipsychotics, in which case clozapine is offered. Most antipsychotics improve schizophrenia symptoms, with clozapine the most effective overall; side effects vary considerably and guide treatment choices. In situations where doctors judge that there is a risk of harm to self or others, they may impose short involuntary hospitalization. Long-term hospitalization is used on a small number of people with severe schizophrenia. In some countries where supportive services are limited or unavailable, long-term hospital stays are more common.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Signs and symptoms', 'Schizophrenia is a mental disorder characterized by significant alterations in perception, thoughts, mood, and behavior. Symptoms are described in terms of positive, negative, and cognitive symptoms. The positive symptoms of schizophrenia are the same for any psychosis and are sometimes referred to as psychotic symptoms. These may be present in any of the different psychoses and are often transient, making early diagnosis of schizophrenia problematic. Psychosis noted for the first time in a person who is later diagnosed with schizophrenia is referred to as a first-episode psychosis (FEP).', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Schizophrenia is a mental disorder characterized by significant alterations in perception, thoughts, mood, and behavior. Symptoms are described in terms of positive, negative, and cognitive symptoms. The positive symptoms of schizophrenia are the same for any psychosis and are sometimes referred to as psychotic symptoms. These may be present in any of the different psychoses and are often transient, making early diagnosis of schizophrenia problematic. Psychosis noted for the first time in a person who is later diagnosed with schizophrenia is referred to as a first-episode psychosis (FEP).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Positive symptoms', 'Positive symptoms are those that are not normally experienced, but are present in people during a psychotic episode in schizophrenia, including delusions, hallucinations, and disorganized thoughts, speech and behavior or inappropriate affect, typically regarded as manifestations of psychosis. Hallucinations occur at some point in the lifetimes of 80% of those with schizophrenia and most commonly involve the sense of hearing (most often hearing voices), but can sometimes involve any of the other senses such as taste, sight, smell, and touch. The frequency of hallucinations involving multiple senses is double the rate of those involving only one sense. They are also typically related to the content of the delusional theme. Delusions are bizarre or persecutory in nature. Distortions of self-experience such as feeling that others can hear one''s thoughts (thought broadcasting delusion) or that thoughts are being inserted into one''s mind, sometimes termed passivity phenomena, are also common. The type and content of auditory and visual hallucinations is influenced by the cultural and social background of the patient. Positive symptoms generally respond well to medication and become reduced over the course of the illness, perhaps linked to the age-related decline in dopamine activity.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Positive symptoms are those that are not normally experienced, but are present in people during a psychotic episode in schizophrenia, including delusions, hallucinations, and disorganized thoughts, speech and behavior or inappropriate affect, typically regarded as manifestations of psychosis. Hallucinations occur at some point in the lifetimes of 80% of those with schizophrenia and most commonly involve the sense of hearing (most often hearing voices), but can sometimes involve any of the other senses such as taste, sight, smell, and touch. The frequency of hallucinations involving multiple senses is double the rate of those involving only one sense. They are also typically related to the content of the delusional theme. Delusions are bizarre or persecutory in nature. Distortions of self-experience such as feeling that others can hear one''s thoughts (thought broadcasting delusion) or that thoughts are being inserted into one''s mind, sometimes termed passivity phenomena, are also common. The type and content of auditory and visual hallucinations is influenced by the cultural and social background of the patient. Positive symptoms generally respond well to medication and become reduced over the course of the illness, perhaps linked to the age-related decline in dopamine activity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Negative symptoms', 'Negative symptoms are deficits of normal emotional responses, or of other thought processes. The five recognized domains of negative symptoms are: blunted affect – showing flat expressions (monotone) or little emotion; alogia – a poverty of speech; anhedonia – an inability to feel pleasure; asociality – the lack of desire to form relationships, and avolition – a lack of motivation and apathy. Avolition and anhedonia are seen as motivational deficits resulting from impaired reward processing. Reward is the main driver of motivation and this is mostly mediated by dopamine. It has been suggested that negative symptoms are multidimensional and they have been categorised into two subdomains of apathy or lack of motivation, and diminished expression. Apathy includes avolition, anhedonia, and social withdrawal; diminished expression includes blunt affect and alogia. Sometimes diminished expression is treated as both verbal and non-verbal.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Negative symptoms are deficits of normal emotional responses, or of other thought processes. The five recognized domains of negative symptoms are: blunted affect – showing flat expressions (monotone) or little emotion; alogia – a poverty of speech; anhedonia – an inability to feel pleasure; asociality – the lack of desire to form relationships, and avolition – a lack of motivation and apathy. Avolition and anhedonia are seen as motivational deficits resulting from impaired reward processing. Reward is the main driver of motivation and this is mostly mediated by dopamine. It has been suggested that negative symptoms are multidimensional and they have been categorised into two subdomains of apathy or lack of motivation, and diminished expression. Apathy includes avolition, anhedonia, and social withdrawal; diminished expression includes blunt affect and alogia. Sometimes diminished expression is treated as both verbal and non-verbal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Negative symptoms', 'Apathy accounts for around 50% of the most often found negative symptoms and affects functional outcome and subsequent quality of life. Apathy is related to disrupted cognitive processing affecting memory and planning, including goal-directed behaviour. The two subdomains have suggested a need for separate treatment approaches. A lack of distress is another noted negative symptom. A distinction is often made between those negative symptoms that are inherent to schizophrenia, termed primary; and those that result from positive symptoms, from the side effects of antipsychotics, substance use disorder, and social deprivation, termed secondary negative symptoms. Negative symptoms are less responsive to medication and the most difficult to treat. However, if properly assessed, secondary negative symptoms are amenable to treatment. There is some evidence that the negative symptoms of schizophrenia are amenable to psychostimulant medication, although such drugs have varying degrees of risk for causing positive psychotic symptoms.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Apathy accounts for around 50% of the most often found negative symptoms and affects functional outcome and subsequent quality of life. Apathy is related to disrupted cognitive processing affecting memory and planning, including goal-directed behaviour. The two subdomains have suggested a need for separate treatment approaches. A lack of distress is another noted negative symptom. A distinction is often made between those negative symptoms that are inherent to schizophrenia, termed primary; and those that result from positive symptoms, from the side effects of antipsychotics, substance use disorder, and social deprivation, termed secondary negative symptoms. Negative symptoms are less responsive to medication and the most difficult to treat. However, if properly assessed, secondary negative symptoms are amenable to treatment. There is some evidence that the negative symptoms of schizophrenia are amenable to psychostimulant medication, although such drugs have varying degrees of risk for causing positive psychotic symptoms.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Negative symptoms', 'Scales for specifically assessing the presence of negative symptoms, and for measuring their severity, and their changes have been introduced since the earlier scales such as the PANSS that deals with all types of symptoms. These scales are the Clinical Assessment Interview for Negative Symptoms (CAINS), and the Brief Negative Symptom Scale (BNSS) also known as second-generation scales. In 2020, ten years after its introduction, a cross-cultural study of the use of BNSS found valid and reliable psychometric evidence for its five-domain structure cross-culturally. The BNSS can assess both the presence and severity of negative symptoms of the five recognized domains and an additional item of reduced normal distress. It has been used to measure changes in negative symptoms in trials of psychosocial and pharmacological interventions.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Scales for specifically assessing the presence of negative symptoms, and for measuring their severity, and their changes have been introduced since the earlier scales such as the PANSS that deals with all types of symptoms. These scales are the Clinical Assessment Interview for Negative Symptoms (CAINS), and the Brief Negative Symptom Scale (BNSS) also known as second-generation scales. In 2020, ten years after its introduction, a cross-cultural study of the use of BNSS found valid and reliable psychometric evidence for its five-domain structure cross-culturally. The BNSS can assess both the presence and severity of negative symptoms of the five recognized domains and an additional item of reduced normal distress. It has been used to measure changes in negative symptoms in trials of psychosocial and pharmacological interventions.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Schizophrenia: Cognitive symptoms', 'An estimated 70% of those with schizophrenia have cognitive deficits, and these are most pronounced in early-onset and late-onset illness. These are often evident long before the onset of illness in the prodromal stage, and may be present in childhood or early adolescence. They are core features but not considered core symptoms, as are positive and negative symptoms. However, their presence and degree of dysfunction are taken as better indicators of functionality than the presentation of core symptoms. Cognitive deficits become worse at first episode psychosis but then return to baseline, and remain fairly stable over the course of the illness.', 'Wikipedia: Schizophrenia', 'https://en.wikipedia.org/w/index.php?title=Schizophrenia&oldid=1378534918', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'An estimated 70% of those with schizophrenia have cognitive deficits, and these are most pronounced in early-onset and late-onset illness. These are often evident long before the onset of illness in the prodromal stage, and may be present in childhood or early adolescence. They are core features but not considered core symptoms, as are positive and negative symptoms. However, their presence and degree of dysfunction are taken as better indicators of functionality than the presentation of core symptoms. Cognitive deficits become worse at first episode psychosis but then return to baseline, and remain fairly stable over the course of the illness.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder', 'Major depressive disorder (MDD), also known as clinical depression, is a mental disorder characterized by at least two weeks of pervasive low mood, low self-esteem, and loss of interest or pleasure in normally enjoyable activities. Introduced by a group of US clinicians in the mid-1970s, the term was adopted by the American Psychiatric Association for this symptom cluster under mood disorders in the 1980 version of the Diagnostic and Statistical Manual of Mental Disorders (DSM-III), and has become widely used since. The disorder causes the second-most years lived with disability, after lower back pain. The diagnosis of major depressive disorder is based on the person''s experiences, and behavior reported by family or friends, and a mental status examination. There is no laboratory test for the disorder, but blood testing and similar may be done to rule out physical conditions that can cause similar symptoms. The most common time of onset is in a person''s 20s. Men are much less likely to report than women, with approximately 33.2% of men and 43.0% of women with depressive symptoms reporting seeking help, possibly due to pressures of masking for men. The course of the disorder varies widely, from one episode lasting months to a lifelong disorder with recurrent episodes.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Major depressive disorder (MDD), also known as clinical depression, is a mental disorder characterized by at least two weeks of pervasive low mood, low self-esteem, and loss of interest or pleasure in normally enjoyable activities. Introduced by a group of US clinicians in the mid-1970s, the term was adopted by the American Psychiatric Association for this symptom cluster under mood disorders in the 1980 version of the Diagnostic and Statistical Manual of Mental Disorders (DSM-III), and has become widely used since. The disorder causes the second-most years lived with disability, after lower back pain. The diagnosis of major depressive disorder is based on the person''s experiences, and behavior reported by family or friends, and a mental status examination. There is no laboratory test for the disorder, but blood testing and similar may be done to rule out physical conditions that can cause similar symptoms. The most common time of onset is in a person''s 20s. Men are much less likely to report than women, with approximately 33.2% of men and 43.0% of women with depressive symptoms reporting seeking help, possibly due to pressures of masking for men. The course of the disorder varies widely, from one episode lasting months to a lifelong disorder with recurrent episodes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder', 'Those with major depressive disorder are typically treated with psychotherapy and antidepressant medication. While a mainstay of treatment, the clinical efficacy of antidepressants is controversial. Hospitalization (which may be involuntary) may be necessary in cases with associated self-neglect or a significant risk of harm to self or others. Major depressive disorder is believed to be caused by a combination of genetic, environmental, and psychological factors, with about 40% of the risk being genetic. Risk factors include a family history of the condition, major life changes, childhood traumas, environmental lead exposure, certain medications, chronic health problems, and substance use disorders. It can negatively affect a person''s personal life, work life, or education, and cause issues with a person''s sleeping habits, eating habits, and general health.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Those with major depressive disorder are typically treated with psychotherapy and antidepressant medication. While a mainstay of treatment, the clinical efficacy of antidepressants is controversial. Hospitalization (which may be involuntary) may be necessary in cases with associated self-neglect or a significant risk of harm to self or others. Major depressive disorder is believed to be caused by a combination of genetic, environmental, and psychological factors, with about 40% of the risk being genetic. Risk factors include a family history of the condition, major life changes, childhood traumas, environmental lead exposure, certain medications, chronic health problems, and substance use disorders. It can negatively affect a person''s personal life, work life, or education, and cause issues with a person''s sleeping habits, eating habits, and general health.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Signs and symptoms', 'A person facing a major depressive episode may have feelings of hopelessness and self-hatred, and may also experience suicidal ideation and thoughts of self-harm. In many cases, this manifests as a complete loss of emotional reactivity, a neurological protection response known as emotional blunting or anhedonia. Approximately 50% of individuals with MDD report these symptoms. Furthermore MDD frequently co-occurs with complex post-traumatic stress disorder (C-PTSD), particularly in cases involving long term trauma. Other symptoms of depression include poor concentration and memory, withdrawal from social situations and activities, reduced sex drive, irritability, Insomnia is common; in the typical pattern, a person wakes very early and cannot go back to sleep. Hypersomnia, or oversleeping, can also happen, as well as day-night rhythm disturbances, such as diurnal mood variation. Some antidepressants may also cause insomnia due to their stimulating effect. In severe cases, depressed people may have psychotic symptoms. These symptoms include delusions or, less commonly, hallucinations, usually unpleasant. People who have had previous episodes with psychotic symptoms are more likely to have them with future episodes.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'A person facing a major depressive episode may have feelings of hopelessness and self-hatred, and may also experience suicidal ideation and thoughts of self-harm. In many cases, this manifests as a complete loss of emotional reactivity, a neurological protection response known as emotional blunting or anhedonia. Approximately 50% of individuals with MDD report these symptoms. Furthermore MDD frequently co-occurs with complex post-traumatic stress disorder (C-PTSD), particularly in cases involving long term trauma. Other symptoms of depression include poor concentration and memory, withdrawal from social situations and activities, reduced sex drive, irritability, Insomnia is common; in the typical pattern, a person wakes very early and cannot go back to sleep. Hypersomnia, or oversleeping, can also happen, as well as day-night rhythm disturbances, such as diurnal mood variation. Some antidepressants may also cause insomnia due to their stimulating effect. In severe cases, depressed people may have psychotic symptoms. These symptoms include delusions or, less commonly, hallucinations, usually unpleasant. People who have had previous episodes with psychotic symptoms are more likely to have them with future episodes.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Signs and symptoms', 'A depressed person may report multiple physical symptoms such as fatigue, headaches, or digestive problems; physical complaints are the most common presenting problem in developing countries, according to the World Health Organization''s criteria for depression. Appetite often decreases, resulting in weight loss, although increased appetite and weight gain occasionally occur. Major depression significantly affects a person''s family and personal relationships, work or school life, sleeping and eating habits, and general health. Family and friends may notice agitation or lethargy. Older depressed people may have cognitive symptoms of recent onset, such as forgetfulness, and a more noticeable slowing of movements. Depressed children may often display an irritable rather than a depressed mood; most lose interest in school and show a steep decline in academic performance. Diagnosis may be delayed or missed when symptoms are interpreted as "normal moodiness". Elderly people with depression may not present with classical depressive symptoms. Diagnosis and treatment is further complicated in that the elderly are often simultaneously treated with a number of other drugs, and often have other concurrent diseases.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'A depressed person may report multiple physical symptoms such as fatigue, headaches, or digestive problems; physical complaints are the most common presenting problem in developing countries, according to the World Health Organization''s criteria for depression. Appetite often decreases, resulting in weight loss, although increased appetite and weight gain occasionally occur. Major depression significantly affects a person''s family and personal relationships, work or school life, sleeping and eating habits, and general health. Family and friends may notice agitation or lethargy. Older depressed people may have cognitive symptoms of recent onset, such as forgetfulness, and a more noticeable slowing of movements. Depressed children may often display an irritable rather than a depressed mood; most lose interest in school and show a steep decline in academic performance. Diagnosis may be delayed or missed when symptoms are interpreted as "normal moodiness". Elderly people with depression may not present with classical depressive symptoms. Diagnosis and treatment is further complicated in that the elderly are often simultaneously treated with a number of other drugs, and often have other concurrent diseases.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Cause', 'The etiology of depression is not yet fully understood. The biopsychosocial model proposes that biological, psychological, and social factors all play a role in causing depression. The diathesis–stress model specifies that depression results when a preexisting vulnerability, or diathesis, is activated by stressful life events. The preexisting vulnerability can be either genetic, implying an interaction between nature and nurture, or schematic, resulting from views of the world learned in childhood. American psychiatrist Aaron Beck suggested that a triad of automatic and spontaneous negative thoughts about the self, the world or environment, and the future may lead to other depressive signs and symptoms.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'The etiology of depression is not yet fully understood. The biopsychosocial model proposes that biological, psychological, and social factors all play a role in causing depression. The diathesis–stress model specifies that depression results when a preexisting vulnerability, or diathesis, is activated by stressful life events. The preexisting vulnerability can be either genetic, implying an interaction between nature and nurture, or schematic, resulting from views of the world learned in childhood. American psychiatrist Aaron Beck suggested that a triad of automatic and spontaneous negative thoughts about the self, the world or environment, and the future may lead to other depressive signs and symptoms.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Genetics', 'Genes play a major role in the development of depression. Family and twin studies suggest that genetic factors account for nearly 40% of the variation in risk for major depressive disorder. Like most psychiatric disorders, major depression is likely shaped by a combination of many individual genetic influences. In 2018, a genome-wide association study discovered 44 genetic variants linked to risk for major depression; a 2019 study found 102 variants in the genome linked to depression. However, it appears that major depression is less heritable compared to bipolar disorder and schizophrenia. Research focusing on specific candidate genes has been criticized for its tendency to generate false positive findings. There are also other efforts to examine interactions between life stress and polygenic risk for depression.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Genes play a major role in the development of depression. Family and twin studies suggest that genetic factors account for nearly 40% of the variation in risk for major depressive disorder. Like most psychiatric disorders, major depression is likely shaped by a combination of many individual genetic influences. In 2018, a genome-wide association study discovered 44 genetic variants linked to risk for major depression; a 2019 study found 102 variants in the genome linked to depression. However, it appears that major depression is less heritable compared to bipolar disorder and schizophrenia. Research focusing on specific candidate genes has been criticized for its tendency to generate false positive findings. There are also other efforts to examine interactions between life stress and polygenic risk for depression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Other health problems', 'Depression can also arise after a chronic or terminal medical condition, such as HIV/AIDS or asthma, and may be labeled "secondary depression". It is unknown whether the underlying diseases induce depression through effect on quality of life, or through shared etiologies (such as degeneration of the basal ganglia in Parkinson''s disease or immune dysregulation in asthma). Depression may also be iatrogenic (the result of healthcare), such as drug-induced depression. Therapies associated with depression include interferons, beta blockers, isotretinoin, contraceptives, cardiac agents, anticonvulsants, and hormonal agents. Celiac disease is another possible contributing factor. Substance use in early age is associated with increased risk of developing depression later in life. Depression occurring after giving birth is called postpartum depression and is thought to be the result of hormonal changes associated with pregnancy. Seasonal affective disorder, a type of depression associated with seasonal changes in sunlight, is thought to be triggered by decreased sunlight. A 2025 study found that, among more than 172,500 adults in the UK aged 39 and older, those with a history of depression experienced the onset of chronic illnesses approximately 30% earlier than those without depression. A meta-analysis linking depression to elevated levels of C-reactive protein (CRP) cites research indicating that inflammation might contribute to depression.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Depression can also arise after a chronic or terminal medical condition, such as HIV/AIDS or asthma, and may be labeled "secondary depression". It is unknown whether the underlying diseases induce depression through effect on quality of life, or through shared etiologies (such as degeneration of the basal ganglia in Parkinson''s disease or immune dysregulation in asthma). Depression may also be iatrogenic (the result of healthcare), such as drug-induced depression. Therapies associated with depression include interferons, beta blockers, isotretinoin, contraceptives, cardiac agents, anticonvulsants, and hormonal agents. Celiac disease is another possible contributing factor. Substance use in early age is associated with increased risk of developing depression later in life. Depression occurring after giving birth is called postpartum depression and is thought to be the result of hormonal changes associated with pregnancy. Seasonal affective disorder, a type of depression associated with seasonal changes in sunlight, is thought to be triggered by decreased sunlight. A 2025 study found that, among more than 172,500 adults in the UK aged 39 and older, those with a history of depression experienced the onset of chronic illnesses approximately 30% earlier than those without depression. A meta-analysis linking depression to elevated levels of C-reactive protein (CRP) cites research indicating that inflammation might contribute to depression.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'personality-disorders', 'Major depressive disorder: Environmental', 'Adverse childhood experiences (incorporating childhood abuse, neglect and family dysfunction) markedly increase the risk of major depression, especially if more than one type. Childhood trauma also correlates with severity of depression, poor responsiveness to treatment and length of illness. Some are more susceptible than others to developing mental illness such as depression after trauma, and various genes have been suggested to control susceptibility. Couples in unhappy marriages have a higher risk of developing clinical depression. There appears to be a link between air pollution and depression and suicide. There may be an association between long-term PM2.5 exposure and depression, and a possible association between short-term PM10 exposure and suicide. In a review, people who lived alone were found to have a 42% greater risk of depression.', 'Wikipedia: Major depressive disorder', 'https://en.wikipedia.org/w/index.php?title=Major_depressive_disorder&oldid=1375960536', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'personality-disorders' and body = 'Adverse childhood experiences (incorporating childhood abuse, neglect and family dysfunction) markedly increase the risk of major depression, especially if more than one type. Childhood trauma also correlates with severity of depression, poor responsiveness to treatment and length of illness. Some are more susceptible than others to developing mental illness such as depression after trauma, and various genes have been suggested to control susceptibility. Couples in unhappy marriages have a higher risk of developing clinical depression. There appears to be a link between air pollution and depression and suicide. There may be an association between long-term PM2.5 exposure and depression, and a possible association between short-term PM10 exposure and suicide. In a review, people who lived alone were found to have a 42% greater risk of depression.');
